(()=>{const release=document.querySelector('meta[name="site-release"]')?.content;if(!/^[a-f0-9]{12}$/.test(release||"")||!window.fetch)return;let checking=false;const checkVersion=async()=>{if(checking)return;checking=true;const controller=new AbortController;const timeout=setTimeout(()=>controller.abort(),3e3);try{const endpoint=new URL("site-version.json",location.href);endpoint.searchParams.set("check",Date.now().toString(36));const response=await fetch(endpoint,{cache:"no-store",signal:controller.signal});if(!response.ok)return;const latest=(await response.json()).id;if(!/^[a-f0-9]{12}$/.test(latest||""))return;const page=new URL(location.href);if(latest===release){if(page.searchParams.has("site-version")){page.searchParams.delete("site-version");history.replaceState(history.state,"",page.href)}}else if(page.searchParams.get("site-version")!==latest){page.searchParams.set("site-version",latest);location.replace(page.href)}}catch(_){}finally{clearTimeout(timeout);checking=false}};checkVersion();window.addEventListener("pageshow",event=>{if(event.persisted)checkVersion()})})();
